# "The Letter" series in the Vox template (AK 30 Sep 2026: "Use VOX template for all").
# Scripts: DarwinWiki contentengine/youtube/letters_scripts/ (each script's fact sheet is the source of truth).
# Kept apart from vx_scripts.py (the daily filings videos) so the two sessions never edit the same file.
# Each beat: T(ch, key, say, cap, scene). say = spoken (numbers as words); cap = on-screen captions (numerals).
# "at"/"hl" phrases must occur in `say` (build checks). Clips are real PDF crops; their phrase is verbatim source text.

def T(ch, key, say, cap, scene): return dict(ch=ch, key=key, say=say, cap=cap, scene=scene)
def title(ch, key, lines, say): return T(ch, key, say, None, dict(type="title", lines=lines))
def K(say, *lines, kicker=None):   # kinetic: lines = (text, at, em-list)
    return dict(type="kinetic", kicker=kicker, lines=[dict(t=t, at=a, em=e) for t, a, e in lines])

DISC_SAY = "A quick note first. This is educational research from the original letters, not investment advice. Moat and Margin is not a SEBI registered adviser."
DISC_CAP = "A quick note first. This is educational research from the original letters, not investment advice. Moat & Margin is not a SEBI-registered adviser."
DISC = dict(type="strips", items=[dict(text="EDUCATIONAL RESEARCH", at="educational research"), dict(text="NOT INVESTMENT ADVICE", at="not investment advice"), dict(text="NOT SEBI-REGISTERED", at="not a SEBI", red=True)])
NOMAD_SRC = "Nomad Investment Partnership letters · compiled edition (Sleep, Zakaria & Co.)"

